"""Integration configuration types.

``integrations.yml`` is copied into the model archive at train time. Runtime
readers use different copies:

- The orchestrator names its group in ``agent.yml``. Definitions are read
  from the live ``model_groups`` section so a restart picks up LLM changes
  without retraining. A leftover ``llm:`` section is invalid.
- Model groups used for reference embeddings are resolved from the packaged
  snapshot so query vectors match the index built at train time.

These types are the validated representation of that file.
"""

from __future__ import annotations

from typing import Any, Literal, Optional
from urllib.parse import urlparse

from pydantic import BaseModel, ConfigDict, Field, model_validator

from rasa.core.config.available_endpoints import MCPMetaMapConfig
from rasa.shared.agents.auth.utils import validate_secrets_in_params
from rasa.shared.project_structure import MANTLE_AGENT_FILE, MANTLE_INTEGRATIONS_FILE

LEFTOVER_LLM_SECTION_MESSAGE = (
    f"'{MANTLE_INTEGRATIONS_FILE}' must not contain an 'llm:' section. "
    f"Set 'orchestrator.model_group' in '{MANTLE_AGENT_FILE}' instead."
)

# Same fold as CALM ``MCPServerConfig``: these stay on the model, everything
# else (token / api_key / oauth / module, plus header knobs) lands in
# ``additional_params`` for AgentAuthManager. ``pre_call_hook`` is a first-class
# CALM field and is intentionally omitted here.
_MCP_ADDITIONAL_PARAMS_KEY = "additional_params"
_MCP_SERVER_BASE_FIELDS = frozenset(
    {"name", "url", "type", "meta_map", "tool_timeout", _MCP_ADDITIONAL_PARAMS_KEY}
)
_MCP_SUPPORTED_TYPES = frozenset({"http", "https"})
_MCP_AUTH_KEYS = frozenset({"token", "api_key", "oauth", "module"})
_MCP_UNSUPPORTED_FIELDS = frozenset(
    {"auth", "token_env", "pre_call_hook", "protocol_version"}
)


def _infer_mcp_server_type(url: str) -> str:
    """Infer ``http`` / ``https`` from the URL scheme."""
    scheme = urlparse(url).scheme.lower()
    if scheme in _MCP_SUPPORTED_TYPES:
        return scheme
    displayed = scheme or "no scheme"
    raise ValueError(f"MCP server URL must use http or https, got {displayed!r}.")


class MCPServerSpec(BaseModel):
    """One MCP tool server from ``integrations.yml``.

    A named record. Extra keys fold into ``additional_params``. ``type`` is
    inferred from the URL when omitted. ``tool_timeout`` is its own field.
    ``pre_call_hook`` and ``meta_map.from_slots`` are rejected.
    """

    model_config = ConfigDict(frozen=True)

    name: str = Field(
        ...,
        min_length=1,
        pattern=r"^[A-Za-z0-9][A-Za-z0-9_.-]*$",
        description=(
            "The name of the MCP server. Same charset as ``mcp/<name>:<tool>`` "
            "imports: letters, digits, ``_``, ``.``, and ``-``."
        ),
    )
    url: str = Field(..., description="The URL of the MCP server.")
    type: str = Field(
        default="http",
        description="The type of the MCP server (``http`` or ``https``).",
    )
    additional_params: dict[str, Any] = Field(
        default_factory=dict,
        description="Auth and extra transport parameters for the MCP server.",
    )
    meta_map: Optional[MCPMetaMapConfig] = Field(
        default=None,
        description="Optional static _meta sent with MCP tool calls.",
    )
    tool_timeout: Optional[float] = Field(
        default=None,
        gt=0,
        allow_inf_nan=False,
        description="Per-call timeout in seconds for tools on this server.",
    )

    @model_validator(mode="before")
    @classmethod
    def collect_additional_params(cls, values: Any) -> Any:
        """Fold top-level extras into ``additional_params`` (same as CALM)."""
        if not isinstance(values, dict):
            return values
        data = dict(values)
        extras = {k: v for k, v in data.items() if k not in _MCP_SERVER_BASE_FIELDS}
        if extras:
            merged = dict(data.get(_MCP_ADDITIONAL_PARAMS_KEY) or {})
            merged.update(extras)
            data[_MCP_ADDITIONAL_PARAMS_KEY] = merged
            for key in extras:
                data.pop(key, None)
        if not data.get("type") and data.get("url"):
            data["type"] = _infer_mcp_server_type(str(data["url"]))
        return data

    @model_validator(mode="after")
    def validate_server(self) -> "MCPServerSpec":
        """Validate type, URL, auth, secrets, and unsupported CALM-only keys."""
        if self.type not in _MCP_SUPPORTED_TYPES:
            raise ValueError(f"Invalid MCP server type: {self.type}")
        if not self.name.strip() or not self.url.strip():
            raise ValueError("Name and URL cannot be empty")
        url_scheme = urlparse(self.url).scheme.lower()
        if url_scheme not in _MCP_SUPPORTED_TYPES:
            displayed = url_scheme or "no scheme"
            raise ValueError(
                f"MCP server URL must use http or https, got {displayed!r}."
            )
        unsupported = sorted(
            _MCP_UNSUPPORTED_FIELDS.intersection(self.additional_params)
        )
        if unsupported:
            raise ValueError(
                "Unsupported MCP server field(s): "
                f"{unsupported}. Any additional key is currently not supported."
            )
        configured_auth = sorted(_MCP_AUTH_KEYS.intersection(self.additional_params))
        if len(configured_auth) > 1:
            raise ValueError(
                "Configure at most one MCP transport auth method; found "
                f"{configured_auth}."
            )
        if self.additional_params:
            validate_secrets_in_params(self.additional_params, "MCP server")
        if self.meta_map is not None and self.meta_map.from_slots is not None:
            raise ValueError(
                "meta_map.from_slots is not supported. Use meta_map.static "
                "for per-call MCP _meta."
            )
        return self


class KnowledgeStoreConfig(BaseModel):
    """Config for one searchable knowledge store from ``knowledge_stores:``.

    A store the agent can retrieve from via the built-in ``search_knowledge``
    tool. ``type`` selects the vector-store backend (reusing the existing
    :mod:`rasa.core.information_retrieval` backends); ``embeddings`` names a
    model group resolved from the packaged snapshot so query vectors match the
    index built at train time. ``top_k`` bounds how many snippets a query
    returns; ``namespace`` is an optional provider-specific collection/section
    selector.
    """

    model_config = ConfigDict(frozen=True, extra="forbid", hide_input_in_errors=True)

    id: str = Field(min_length=1)
    type: Literal["qdrant", "milvus", "faiss"]
    embeddings: str = Field(min_length=1)
    top_k: int = Field(default=4, gt=0)
    namespace: str | None = None


class IntegrationConfig(BaseModel):
    """Sections of ``integrations.yml`` this model owns.

    ``channels`` and ``tracing`` are real sections parsed elsewhere, so unknown
    keys stay ignored. A leftover ``llm:`` key is rejected: the orchestrator
    names its group in ``agent.yml``.
    """

    model_config = ConfigDict(frozen=True, hide_input_in_errors=True)

    mcp_servers: list[MCPServerSpec] = Field(default_factory=list)
    knowledge_stores: list[KnowledgeStoreConfig] = Field(default_factory=list)
    model_groups: list[dict[str, Any]] = Field(default_factory=list)
    """Raw model-group declarations (``{id, models: [...]}``).

    Parsed/validated via ``ModelGroupConfig`` in ``config/validation.py`` and
    resolved at runtime by ``resolve_model_client_config``.
    """

    @model_validator(mode="before")
    @classmethod
    def _reject_leftover_llm_section(cls, values: Any) -> Any:
        """Reject ``llm:`` so dropping the field does not hide the section."""
        if isinstance(values, dict) and "llm" in values:
            raise ValueError(LEFTOVER_LLM_SECTION_MESSAGE)
        return values
